canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='touch'||e.button!==0||!playing||dialog.opened||!personCombat())return;const r=canvas.getBoundingClientRect();pointerAim.active=true;pointerAim.fire=true;pointerAim.x=(e.clientX-r.left)*canvas.width/r.width;pointerAim.y=(e.clientY-r.top)*canvas.height/r.height;e.preventDefault();canvas.setPointerCapture?.(e.pointerId);canvas.focus({preventScroll:true});});
