function openTestGate(){
 if(testUnlocked){openTestMenu();return;}
 dialog.open('Test mode','test-gate',{eyebrow:'A SEPARATE PRACTICE RANGE'});
 dialog.html('<p>Try the combat systems in isolation. Your voyage and shared captain stay where you left them.</p><form id="testGateForm" class="test-gate"><label for="testPassword">Test password</label><input id="testPassword" type="password" inputmode="numeric" autocomplete="off" maxlength="20" required><p id="testGateError" class="danger-note" role="status"></p><button class="button-primary" type="submit">Enter test mode →</button></form>');
 $('testGateForm').onsubmit=e=>{e.preventDefault();if(!unlockTestMode($('testPassword').value)){hudText($('testGateError'),'That password did not match.');$('testPassword').select();return;}testUnlocked=true;openTestMenu();};
 $('testPassword').focus();
}
function openTestMenu(){
 if(!testUnlocked){openTestGate();return;}
 const hulls=testEnemyChoices();if(!hulls.some(h=>h.id===testConfig.enemyClassId))testConfig.enemyClassId=hulls[0].id;
 dialog.open('The proving ground','test-menu',{eyebrow:'TEST MODE / ISOLATED & UNSAVED',wide:true});
 dialog.html('<p class="section-note">One starting cutter. One pirate. Practice the systems, then return to your voyage. These exercises reveal only a small selection of early hulls.</p><div class="test-layout"><div><h3>Choose an exercise</h3><div id="testScenarios" class="test-scenarios"></div></div><div class="test-target"><span class="eyebrow">ENEMY HULL</span><canvas id="testShipPreview" aria-label="Selected practice enemy"></canvas><label for="testEnemy">Practice opponent</label><select id="testEnemy"></select><p id="testHullDetail" class="mini"></p><p class="mini muted">Your cutter and equipment are fixed. This range has no story rewards or saved progression.</p></div></div><div class="test-launch"><p id="testGoal"></p><button id="launchTest" class="button-primary">Begin exercise →</button></div>');
 const select=$('testEnemy');for(const hull of hulls){const option=document.createElement('option');option.value=hull.id;option.textContent=hull.name;select.append(option);}select.value=testConfig.enemyClassId;
 const renderHull=()=>{testConfig.enemyClassId=select.value;const hull=hulls.find(h=>h.id===select.value);shipPreview($('testShipPreview'),hull.id);hudText($('testHullDetail'),`${hull.subtitle} · ${hull.berths} berths. Its exterior and interior use the same hull.`);};select.onchange=renderHull;
 const renderScenarios=()=>{$('testScenarios').replaceChildren();for(const scenario of TEST_SCENARIOS){const button=document.createElement('button');button.className='test-scenario'+(testConfig.scenario===scenario.id?' selected':'');button.setAttribute('aria-pressed',String(testConfig.scenario===scenario.id));button.innerHTML=`<strong>${esc(scenario.title)}</strong><small>${esc(scenario.description)}</small>`;button.onclick=()=>{testConfig.scenario=scenario.id;renderScenarios();};$('testScenarios').append(button);}hudText($('testGoal'),TEST_SCENARIOS.find(s=>s.id===testConfig.scenario).goal);};
 renderScenarios();renderHull();$('launchTest').onclick=()=>enterTestSession(createTestSession({...testConfig,seed:'range-'+Date.now()}));
}
function enterTestSession(session){
 if(network){toast('Sign off from the shared galaxy before opening an isolated exercise.','bad');return;}
 if(!testSession)testReturn={game,stored,tracked};
 testSession=session;game=session.game;testConfig={scenario:session.scenarioId,enemyClassId:session.enemyClassId};testOutcome='';
 playing=true;dialog.close();$('welcome').hidden=true;$('testBar').hidden=false;document.body.classList.remove('welcome-active');document.body.classList.add('test-mode');
 hudText($('testScenarioName'),session.scenario.title);tracked=session.targetId;surface=null;surfaceKey='';surfaceTarget=null;personVisualOffset={x:0,y:0};personPredictedAt=null;personVisualAt=null;stepAccumulator=0;saveTimer=0;
 combatPresentation.reset();combatFeed.length=0;worldPresentation.reset();clearPointerAim();controls.clear();localShotAt=-Infinity;game.drainEvents();renderer.lastSystem=null;ensureSurface();audio.unlock();resize();updateHUD();canvas.focus({preventScroll:true});toast(session.goal,'info',6500);
}
function retryTest(){if(testSession)enterTestSession(resetTestSession(testSession));}
function exitTestMode(){
 if(!testSession)return;dialog.close();controls.clear();clearPointerAim();combatPresentation.reset();combatFeed.length=0;worldPresentation.reset();
 const prior=testReturn;game=prior.game;stored=prior.stored;tracked=prior.tracked;testSession=null;testReturn=null;testOutcome='';playing=false;surface=null;surfaceKey='';surfaceTarget=null;personVisualOffset={x:0,y:0};
 $('testBar').hidden=true;$('combatPanel').hidden=true;$('welcome').hidden=false;document.body.classList.remove('test-mode','person-mode','combat-active');document.body.classList.add('welcome-active');$('continueButton').hidden=!stored;renderer.lastSystem=null;resize();updateConnectionHUD();
}
function openTestControls(){
 if(!testSession){openTestGate();return;}const status=testSessionStatus(testSession);
 dialog.open(testSession.scenario.title,'test-controls',{eyebrow:'TEST MODE / YOUR VOYAGE IS UNCHANGED'});dialog.html(`<div class="guide-card"><strong>${esc(status.title)}</strong><p>${esc(status.detail)}</p></div><p>${esc(testSession.goal)}</p>`);
 dialog.choices([{label:'Resume exercise',action:()=>dialog.close()},{label:'Weapon & boarding controls',action:openCombatHelp},{label:'Retry this exercise',detail:'Restore the same target, ships, and crew deck.',action:retryTest},{label:'Choose another exercise',action:openTestMenu},{label:'Exit to main menu',action:exitTestMode}]);
}
function openCombatHelp(){
 const boarding=game.state.boarding,mp=game.state.multiplayer??{};
 dialog.open('Your sidearm & the deck','combat-help',{eyebrow:'PERSON COMBAT'});
 dialog.html(`<div class="weapon-brief"><span class="sidearm-glyph" aria-hidden="true"></span><div><h3>${esc(SIDEARM.name)}</h3><p>Included in your standard airlock kit. Its cell recharges between shots; it is ready when the weapon panel says READY.</p></div></div><h3>Aim, then fire</h3><p><strong>Desktop:</strong> WASD walks. Move the mouse over the deck or hold arrow keys to aim independently. Left-click or hold Space to fire. E uses nearby stations and airlocks.</p><p><strong>Touch:</strong> the left stick walks; push the right stick toward a target to aim and fire. The FIRE button fires at the marked aim-assist target.</p><p>With no manual aim, the bracket marks a nearby visible hostile. Firing into a wall or empty space still produces a shot. A damage number confirms a hit; the DOWN label identifies the attacker. Your sidearm never fires by itself.</p><h3>Two ships remain in space</h3><p>Crossing an airlock puts you on that target’s actual deck. Both hulls remain exposed to outside fire. Reach the entry airlock to return across the tether, or clear the defenders and use the target’s helm. A destroyed hull cannot be used as an escape ship.</p><p>Friendly crew are protected. In a shared galaxy, declaring hostility makes ship and boarding combat deliberate. Hostile occupation blocks recovery into that ship’s bunks.</p>`);
 const choices=[{label:'Back to the deck',action:()=>dialog.close()}];if(boarding?.kind==='assault'||mp.returnVesselId)choices.push({label:'Return across the tether',detail:'Stand beside the entry airlock. Your origin ship must still be nearby and intact.',action:()=>runDeckAction('returnToOwnShip')});if(testSession)choices.push({label:'Exercise controls',action:openTestControls});dialog.choices(choices);
}
function openBoardingBrief(target){
 const enemy=game.system.enemies.find(e=>e.id===target.id);if(!enemy)return;const hull=getShipClass(enemy.cabinClass??enemy.classId);
 dialog.open(enemy.name??target.name,'boarding-brief',{eyebrow:'DISABLED CONTACT / BOARDING TETHER'});
 dialog.html(`<div class="ship-profile"><canvas id="boardingPortrait" aria-label="Boarding target hull"></canvas><div><h3>${esc(enemy.name??target.name)}</h3><p>${esc(hull.name)} · ${hull.berths} berths<br>Hull ${Math.round(enemy.hp/enemy.maxHp*100)}% remaining · Engines disabled</p></div></div><div class="guide-card"><strong>Pulse sidearm equipped</strong><p>WASD moves. Mouse or arrows aim. Click or Space fires. On touch, use the right stick to aim and fire.</p></div><p>You will enter this ship, leaving your own alongside. Both remain vulnerable. Clear the deck to use its helm, or return through the entry airlock.</p>`);shipPreview($('boardingPortrait'),hull.id);
 dialog.choices([{label:'Board the target ship',action:async()=>{if(result(await invoke('boardEnemy',{id:target.id}))){dialog.close();surfaceKey='';ensureSurface();controls.clear();toast('Target deck · Pulse sidearm ready. Aim, then fire.','good',5500);}}},{label:'Keep flying',action:()=>dialog.close()}]);
}
async function runDeckAction(method,args={}){if(result(await invoke(method,args))){dialog.close();surface=null;surfaceKey='';surfaceTarget=null;ensureSurface();controls.clear();clearPointerAim();updateHUD();}}
function updateCombatHUD(){
 const boarding=game.state.boarding,visible=playing&&game.state.mode==='person'&&!!boarding,panel=$('combatPanel');if(panel.hidden===visible){panel.hidden=!visible;labelLayoutDirty=true;}
 document.body.classList.toggle('combat-active',visible);if(!visible)return;const active=boarding.phase==='active',down=game.state.person.health<=0||game.state.person.down,aim=combatPreview,remaining=(boarding.enemies??[]).filter(e=>e.health>0).length;
 hudText($('weaponName'),SIDEARM.name);hudText($('weaponState'),down?'DOWN':active?(elapsed-localShotAt<SIDEARM.cooldown?'CYCLING':'READY'):'HOLSTERED');panel.classList.toggle('deck-secure',!active);
 hudText($('aimStatus'),down?'INCAPACITATED · Waiting for recovery':!active?'Deck secure · Use the helm or entry airlock':aim?.blocked?'WALL BLOCKING SHOT':aim?.target?(aim.manual?'AIM: ':'ASSIST: ')+(aim.target.name??'Hostile'):aim?.manual?'MANUAL AIM · No target in sights':'AIM ASSIST · No visible target');
 hudText($('combatCount'),active?`${remaining} hostile${remaining===1?'':'s'} · ${boarding.kind==='assault'?'Target deck · Both hulls exposed':'Defend this ship'}`:'Crew cleared · Outside fire can still hit the hull');
 if(boarding.kind==='assault'){const origin=network?onlineSnapshot?.fleet?.find(v=>v.id===game.state.multiplayer?.returnVesselId):game.state.ship;if(origin)hudText($('combatCount'),`${remaining} hostile${remaining===1?'':'s'} · Origin hull ${Math.ceil(origin.hull)} / ${Math.ceil(origin.maxHull)}`);}
 const recent=combatFeed.filter(e=>elapsed-e.at<7).slice(-3);if(hudHTML($('combatFeed'),recent.map(e=>`<div>${esc(e.text)}</div>`).join('')))labelLayoutDirty=true;
}
function recordCombatFeed(text){combatFeed.push({text,at:elapsed});if(combatFeed.length>5)combatFeed.shift();hudDirty=true;}
function processCombatEvent(event){
 const accepted=combatPresentation.push(event,elapsed);if(!accepted)return false;
 const id=network?.passport?.captainId??game.playerId??'local',local=event.attackerId===id||!network&&event.attackerId==='local';
 if(event.type==='person-shot'){audio.play(local?'sidearm':event.team==='hostile'?'enemyShot':'crewShot');if(local)localShotAt=elapsed;}
 if(event.type==='person-hit'){if(event.targetId===id)audio.play('personHit');else if(local)audio.play('sidearmHit');}
 if(['boarder-down','person-down','crew-death'].includes(event.type)){audio.play('personDown');recordCombatFeed(`${event.targetName??event.name??'Crew member'} down · ${local?'Your shot':event.actorName??event.attackerName??'Boarding combat'}`);}
 hudDirty=true;return true;
}
function openVesselContact(vesselId){
 const v=onlineSnapshot?.fleet?.find(item=>item.id===vesselId);if(!v){openOnline();return;}const mp=game.state.multiplayer??{},owner=onlineSnapshot?.presence?.find(c=>c.captainId===v.ownerId),aboard=mp.aboardVesselId===v.id;
 dialog.open(v.name??'Vessel contact','vessel-contact',{eyebrow:`${getShipClass(v.classId).name.toUpperCase()} / ${v.hostile?'HOSTILE CONTACT':'SHIP CONTACT'}`});
 const range=Number.isFinite(v.x)?Math.round(Math.hypot(v.x-game.state.ship.x,v.y-game.state.ship.y)):null;
 dialog.html(`<p>${owner?`${esc(owner.name)}’s vessel · `:''}${v.occupants??0} aboard · ${v.berths} berths${range!==null&&!aboard?` · ${range} m away`:''}</p><div class="stat-grid"><div class="stat-cell"><small>HULL</small><strong>${Math.ceil(v.hull??0)} / ${Math.ceil(v.maxHull??0)}</strong></div><div class="stat-cell"><small>STATUS</small><strong class="contact-state">${v.destroyed?'DESTROYED':v.occupation?.contested?'CONTESTED':v.disabled?'DISABLED':v.hostile?'HOSTILE':'UNDER WAY'}</strong></div></div><p>${v.occupation?.contested?'Hostile boarders are aboard. This ship cannot be a recovery destination.':'Boarding changes which deck you occupy. Your own ship stays where you leave it.'}</p>`);
 const actions=[];if(!aboard&&!v.hostile)actions.push({label:'Board with permission',disabled:!v.canBoard,detail:v.canBoard?'Meet at the same port or approach within boarding range.':'The owner has not granted access.',action:()=>runDeckAction('boardShip',{vesselId:v.id})});
 if(!aboard&&v.canDeclareHostility)actions.push({label:'Declare this ship hostile',warning:true,detail:'Both sides can damage each other. Disable its hull before attempting forced boarding.',action:async()=>{if(result(await invoke('declareHostility',{vesselId:v.id})))openVesselContact(v.id);}});
 if(!aboard&&v.hostile)actions.push({label:'Board the hostile ship',disabled:!v.canHostileBoard,detail:v.canHostileBoard?'Cross onto the actual target deck. Both hulls remain in space.':'Disable the hull and approach close enough to board.',action:()=>runDeckAction('boardHostileShip',{vesselId:v.id})});
 if(aboard&&(mp.canTakeHelm||v.canTakeHelm))actions.push({label:'Use this ship’s helm',detail:'Reach its helm. The vessel keeps its existing damage.',action:()=>runDeckAction('takeCapturedHelm')});
 if(aboard&&mp.returnVesselId)actions.push({label:'Return across the tether',detail:'Reach the airlock; your origin ship must remain close enough.',action:()=>runDeckAction('returnToOwnShip')});
 actions.push({label:'Back to nearby ships',action:openOnline},{label:'Return to the world',action:()=>dialog.close()});dialog.choices(actions);
}

function start(fresh){if(testSession){openTestControls();return;}if(network){network.disconnect();network=null;onlineSnapshot=null;connectionState='offline';game=stored?Game.fromSave(stored):new Game('farwake-'+Date.now());}audio.unlock();if(!fresh&&stored){game=Game.fromSave(stored);surface=null;surfaceKey='';}if(fresh){game=new Game('farwake-'+Math.floor(Date.now()/1000));surface=null;surfaceKey='';tracked='kettle';}playing=true;$('welcome').hidden=true;document.body.classList.remove('welcome-active');ensureSurface(false);game.drainEvents();saveNow();updateHUD();canvas.focus({preventScroll:true});if(!fresh&&game.state.pendingEncounter)openEncounter(game.getEncounter());else toast(fresh?'Your ship, Cinder, is beside Kettle Station. Dock to meet Iona and find work.':'Welcome back, captain. Your voyage is right where you left it.','good',6500);}
function saveNow(){if(testSession){hudText($('saveState'),'TEST · UNSAVED');return true;}if(!playing)return;if(network){$('saveState').textContent=network.connected?'SHARED GALAXY':'RECONNECTING';return network.connected;}const ok=saveGame(game);if(ok)stored=game.state;return ok;}
function result(r,{success='',refresh=null}={}){if(!r?.ok){toast(r?.reason??r?.message??'That action is unavailable.','bad');return false;}if(success)toast(success,'good');processEvents();saveNow();if(refresh)refresh();updateHUD();return true;}
async function command(name){if(name==='online'){openOnline();return;}if(name==='pause'){if(dialog.opened)dialog.close();else openSettings();return;}if(!playing)return;if(name==='galaxy')openMap(game.state.systemId,game.state.mode==='person'?'local':'galaxy');else if(name==='journal')openJournal();else if(name==='ship')openShip();else if(name==='cabin')enterCabin();else if(name==='interact')interact();else if(name==='scan')scanNearest();else if(name==='primaryDown'&&game.state.mode==='person'&&!armedOnFoot()){if(elapsed-lastPrimary>.25){lastPrimary=elapsed;wasFire=true;interact();}}else if(name==='mine'&&game.state.mode==='person')openJournal('missions');}
function ensureSurface(reset=false){if(game.state.mode!=='person'){surface=null;surfaceKey='';return;}const body=game.currentBody??game.state.interior?.body??{id:game.state.locationId??'own-ship',name:'Cinder · crew deck',kind:game.state.locationId?.includes('derelict')?'derelict':'ship',crew:game.state.crew};const crew=body.crew??game.state.crew;const key=game.state.systemId+':'+body.id+':'+(game.state.ship.classId??'sparrow')+':'+(body.classId??body.shipClassId??body.shipClass??'')+':'+crew.filter(c=>c.health>0).map(c=>c.id).join(',');if(surfaceKey!==key||reset){controls?.clear();surface=generateSurface({...body,crew},game.state.seed,game.state.flags);surfaceKey=key;if(reset||!isWalkable(surface,game.state.person.x,game.state.person.y))Object.assign(game.state.person,surface.spawn);surfaceTarget=null;updateSurfaceFlags();}}
function updateSurfaceFlags(){if(!surface)return;for(const e of surface.entities){if(e.type==='sample')e.hidden=game.state.flags.includes('done:'+e.id);if(e.type==='crate')e.hidden=game.state.flags.includes('carrying:'+surface.id)||game.state.flags.includes('delivered:'+surface.id);}}
function flag(name){if(!game.state.flags.includes(name))game.state.flags.push(name);}
function currentWorkToken(e){const job=game.state.missions.find(m=>m.type==='work'&&m.targetBody===game.state.locationId&&m.status!=='completed');return `${e.id}:${job?.id??'once'}`;}
function personCombat(){return game.state.mode==='person'&&game.state.boarding?.phase==='active';}
function clearPointerAim(){pointerAim.active=false;pointerAim.fire=false;combatPreview=null;}
function armedOnFoot(){return personCombat()||!!network&&game.state.multiplayer?.crewRole==='weapons';}
function nearby(){if(game.state.mode!=='ship')return surface?nearestEntity(surface,game.state.person,43):null;const local=game.interact();if(local?.type==='board')return local;if(network){const mp=game.state.multiplayer??{},contact=(onlineSnapshot?.fleet??[]).filter(v=>v.id!==(mp.aboardVesselId??mp.ownedVesselId)&&v.systemId===game.state.systemId&&!v.destroyed&&Number.isFinite(v.x)&&Math.hypot(v.x-game.state.ship.x,v.y-game.state.ship.y)<220).sort((a,b)=>distance(a,game.state.ship)-distance(b,game.state.ship))[0];if(contact)return{type:'shared-ship',id:contact.id,name:contact.name??'Nearby ship',vessel:contact};}return local;}
async function interact(){if(!playing||dialog.opened)return;const target=nearby();if(!target){toast(game.state.mode==='ship'?'Fly close to a station, planet, or signal. Hold MINE near asteroids.':'Move close to a person, terminal, or marked workstation.');return;}audio.play('click');if(game.state.mode==='ship'){if(target.type==='dock'){if(result(await invoke('dock',{id:target.id}))){ensureSurface(true);audio.play('dock');toast(`Person mode · ${target.name}. Find the contract exchange or explore.`,'good');saveNow();}}else if(target.type==='signal'){if(target.signal.kind==='derelict'&&!target.signal.resolved){dialog.open(target.name,'derelict',{eyebrow:'UNPOWERED VESSEL'});dialog.html('<p>A freighter drifts with its running lights dark. The docking collar still has pressure. You can investigate the signal from here, or go aboard.</p>');dialog.choices([{label:'Board the freighter',detail:'Explore its holds, find the recorder, and check for survivors.',action:async()=>{dialog.close();if(typeof game.boardDerelict==='function'){if(result(await invoke('boardDerelict',{id:target.id}))){ensureSurface(true);saveNow();}}else{result(await invoke('scan',{id:target.id}));if(game.state.pendingEncounter)openEncounter(game.getEncounter());}}},{label:'Scan its transmission',detail:'Resolve the signal from the safety of your cockpit.',action:async()=>{dialog.close();scanSignal(target.id);}}]);}else scanSignal(target.id);}else if(target.type==='shared-ship'){openVesselContact(target.id);}else if(target.type==='board'){openBoardingBrief(target);}else if(target.type==='parked-ship'){if(result(await invoke('boardParkedShip',{id:target.id}))){surfaceKey='';ensureSurface();}}else if(target.type==='salvage')result(await invoke('salvage',{id:target.id}));else if(target.type==='hail'){dialog.open(target.name,'hail',{eyebrow:'OPEN FREQUENCY'});dialog.html(`<p>“Another small captain out here. Good to see a friendly transponder.”</p><p class="mini">${esc(game.currentSystem.description)}</p>`);dialog.choices([{label:'Ask what is happening nearby',action:async()=>{const r=await invoke('triggerEncounter',{});if(r.ok)openEncounter(r.encounter);else dialog.html('<p>“Quiet, for now. There is always work on the port boards, and the old beacons still have stories to tell.”</p>');}},{label:'Wish them safe travels',action:async()=>dialog.close()}]);}}else handleEntity(target);updateHUD();}
async function scanSignal(id){const r=await invoke('scan',{id:id});if(!result(r))return;if(r.encounter)openEncounter(r.encounter);else if(r.text){dialog.open('Signal recovered','discovery',{eyebrow:'SCANNER RECORD'});dialog.html(`<p>${esc(r.text)}</p>`);dialog.choices([{label:'Add it to the log',action:async()=>dialog.close()}]);}}
async function scanNearest(){if(network&&game.state.mode==='person'&&['scanner','navigation'].includes(game.state.multiplayer?.crewRole)){const r=await invoke('crewAction',{action:'scan'});if(result(r)){if(r.encounter)openEncounter(r.encounter);else if(r.text)toast(r.text,'good');}return;}if(game.state.mode!=='ship')return interact();const sig=game.system.signals.filter(s=>!s.resolved).sort((a,b)=>distance(a,game.state.ship)-distance(b,game.state.ship))[0];if(sig)scanSignal(sig.id);else toast('All local signals have been resolved.');}
async function leaveSurface(){if(game.state.boarding?.kind==='assault'||game.state.multiplayer?.returnVesselId){await runDeckAction('returnToOwnShip');return;}let r;if(game.state.interior&&typeof game.leaveInterior==='function')r=await invoke('leaveInterior');else if(surface?.kind==='ship'&&typeof game.exitCabin==='function')r=await invoke('exitCabin');else if(surface?.kind==='derelict'&&typeof game.leaveDerelict==='function')r=await invoke('leaveDerelict');else r=await invoke('launch');if(result(r)){controls.clear();surface=null;surfaceKey='';surfaceTarget=null;audio.play('dock');saveNow();}}
async function enterCabin(){if(!playing)return;dialog.close();if(game.state.mode!=='ship'){toast('Return to your ship first.');return;}if(typeof game.enterCabin==='function'){if(result(await invoke('enterCabin'))){ensureSurface(true);saveNow();}}else{toast('Crew quarters are available at the next port.');}}
async function handleEntity(e){const type=e.type;if(testSession&&!['exit','station'].includes(type)){openTestControls();return;}
 if(type==='exit'){if(e.data?.stationRole==='helm')openStation(e);else leaveSurface();return;}
 if(type==='jobboard'){openJobs();return;}
 if(type==='mechanic'){if(network){const r=await invoke('surfaceAction',{entityId:e.id,action:'talk'});if(!result(r))return;}else game.recordActivity('talk',{role:'mechanic',token:e.id});if(game.state.interior){dialog.open(e.name,'console',{eyebrow:'RESERVE POWER'});dialog.html('<p>The fabricator is on reserve power. You can calibrate this vessel’s relays, but fitting Cinder with new equipment requires an inhabited port.</p>');dialog.choices([{label:'Find a maintenance relay',action:async()=>{surfaceTarget=surface.entities.find(x=>x.type==='work')?.id;dialog.close();}},{label:'Return to the hold',action:async()=>dialog.close()}]);}else openOutfitter(e);return;}
 if(type==='medic'){openMedic(e);return;}
 if(type==='crew'){openCrew(e);return;}
 if(type==='terminal'){if(e.data?.journal){openJournal();return;}if(e.data?.crew){openCrew();return;}openTerminal(e);return;}
 if(type==='work'){openRepair(e);return;}
 if(type==='station'){openStation(e);return;}
 if(type==='bunk'){openBunk(e);return;}
 if(network&&['crate','delivery','sample'].includes(type)){const r=await invoke('surfaceAction',{entityId:e.id,action:{crate:'pickup',delivery:'deliver',sample:'collect'}[type]});if(result(r)){updateSurfaceFlags();surfaceTarget=type==='crate'?surface.entities.find(x=>x.type==='delivery')?.id:null;toast(r.text??r.message??(type==='crate'?'Freight collected. Carry it to the striped pad.':'Work recorded. Your payment is saved.'),'good');}return;}
 if(type==='crate'){if(game.state.flags.includes('delivered:'+surface.id)){toast('This shipment has been delivered.');return;}flag('carrying:'+surface.id);game.state.person.carrying=true;e.hidden=true;surfaceTarget=surface.entities.find(x=>x.type==='delivery')?.id;toast('Freight collected. Carry it to the striped loading pad.','good');saveNow();return;}
 if(type==='delivery'){if(!game.state.flags.includes('carrying:'+surface.id)){toast('The loading pad is waiting for the freight crate in storage.');surfaceTarget=surface.entities.find(x=>x.type==='crate')?.id;return;}game.state.flags=game.state.flags.filter(f=>f!=='carrying:'+surface.id);flag('delivered:'+surface.id);flag(e.data.flag);game.state.person.carrying=false;const r=game.recordActivity('freight',{token:e.id+':cargo',kind:'cargo'});if(r.first){game.state.credits+=35;game.state.rep.freewake=Math.min(100,game.state.rep.freewake+2);}surfaceTarget=null;toast('Freight delivered · +35 cr · Freewake +2','good');audio.play('quest');processEvents();saveNow();return;}
 if(type==='sample'){if(game.state.flags.includes('done:'+e.id))return;flag('done:'+e.id);flag(e.data.flag);e.hidden=true;if(surfaceTarget===e.id)surfaceTarget=surface.entities.find(x=>x.type==='sample'&&!x.hidden&&x.id!==e.id)?.id??surface.entities.find(x=>x.type==='jobboard')?.id;const r=game.recordActivity('sample',{token:e.id,kind:'sample'});if(r.first){game.state.credits+=15;game.state.rep.lantern=Math.min(100,game.state.rep.lantern+2);}toast('Survey sample catalogued · +15 cr · Lantern +2','good');audio.play('pickup');processEvents();saveNow();return;}
 openNPC(e);
}
function dialogueHeader(e,text){const wrap=document.createElement('div');wrap.className='dialogue-intro';const portraitWrap=document.createElement('div');portraitWrap.className='portrait';const c=document.createElement('canvas');c.width=32;c.height=40;portrait(c,e.color??'#83cbbb',(e.id??'person').length);portraitWrap.append(c);const words=document.createElement('div');words.innerHTML=`<div class="name-tag">${esc(e.name)} / ${esc(e.data?.roleLabel??e.role??'LOCAL CONTACT')}</div><p>${esc(text)}</p>`;wrap.append(portraitWrap,words);dialog.body.append(wrap);}
function resolveRole(e){const aliases={Shipwright:'mechanic',bartender:'refugee',trader:'merchant',settler:'governor',scientist:'archivist',courier:'pilot',survivor:'refugee','Field archivist':'archivist'};return DIALOGUE[e.role]?e.role:aliases[e.role]??(e.data?.story?'archivist':'refugee');}
async function openNPC(e){const role=resolveRole(e),data=DIALOGUE[role]??DIALOGUE.refugee;if(network){const r=await invoke('surfaceAction',{entityId:e.id,action:'talk'});if(!result(r))return;}else game.recordActivity('talk',{role,token:e.id});processEvents();dialog.open(e.name,'npc',{eyebrow:e.data?.story?'PEOPLE OF THE QUIET EARTH':'LOCAL CONVERSATION'});dialogueHeader(e,e.text||data.greeting);const items=[];
 if(e.data?.story){const chapter=game.chapter;items.push({label:'Ask about Earth and the old transmissions',detail:chapter?.brief??'The story continues in the people you meet.',action:async()=>storyConversation(e)});}
 items.push({label:'What is happening around here?',detail:'Listen for rumors, history, and work.',action:async()=>{const rumors=e.data?.rumors??data.rumors;const n=(game.state.stats.talks+game.state.stats.decisions)%rumors.length;dialog.open(e.name,'npc',{eyebrow:'WORD ON THE DOCKS'});dialogueHeader(e,rumors[n]);const available=game.availableEncounters('person');const preferred=available.find(x=>x.tag==='CONSEQUENCE')??available.find(x=>x.conditions?.locationId===game.state.locationId)??available[0];dialog.choices([{label:preferred?'“You sound like you have a story.”':'Keep that in mind',detail:preferred?.title,action:async()=>{if(preferred){const r=await invoke('triggerEncounter',{id:preferred.id});if(r.ok)openEncounter(r.encounter);}else dialog.close();}},{label:'Ask about work',action:openJobs},{label:'Back to the concourse',action:async()=>dialog.close()}]);}});
 if(role==='dockworker'||role==='broker'||role==='merchant'||role==='pilot')items.push({label:'I’m looking for work',detail:'Local maintenance, cargo, mining, surveys, and patrols.',action:openJobs});
 if(role==='pilot'||role==='engineer'||role==='medic'||role==='archivist')items.push({label:'Ask about joining your crew',detail:'A small crew can make a small ship go further.',action:async()=>openCrew(e)});
 items.push({label:'See you around',action:async()=>dialog.close()});dialog.choices(items);saveNow();}
async function storyConversation(e){const chapter=game.chapter;const targeted=game.availableEncounters('person').find(x=>x.conditions?.locationId===game.state.locationId)??game.availableEncounters('person').find(x=>x.conditions?.systemId===game.state.systemId);if(targeted){const r=await invoke('triggerEncounter',{id:targeted.id});if(r.ok){openEncounter(r.encounter);return;}}dialog.open(e.name,'story',{eyebrow:'THE QUIET EARTH'});dialogueHeader(e,chapter?chapter.brief:'The old home is speaking again. Your log carries the choices that made that possible.');if(chapter){const p=document.createElement('div');p.className='guide-card';p.innerHTML=`<span class="eyebrow">${esc(chapter.title)}</span><p>${esc(chapter.objective)}</p>`;dialog.body.append(p);}const items=[];if(game.state.systemId==='vesper'&&game.hasFlag('first_fold_done')&&!game.hasFlag('archive_decoded')){items.push({label:'Help restore the archive array',detail:'Find and calibrate a maintenance relay in this station.',action:async()=>{surfaceTarget=surface.entities.find(x=>x.type==='work')?.id;dialog.close();toast('Find an amber maintenance relay. Its panel needs calibration.','good');}});}items.push({label:'Show the mission log',action:async()=>openJournal('missions')},{label:'I’ll keep looking',action:async()=>dialog.close()});dialog.choices(items);}
async function openTerminal(e){if(network){const r=await invoke('surfaceAction',{entityId:e.id,action:'read'});if(!result(r))return;}else game.recordActivity('explore',{token:e.id});if(e.data?.loreId&&LORE.some(l=>l.id===e.data.loreId)&&!game.state.knownLore.includes(e.data.loreId))game.state.knownLore.push(e.data.loreId);const targeted=game.availableEncounters('person').find(x=>x.conditions?.locationId===game.state.locationId);if(targeted&&(e.data?.story||['stillwater','earth','listening','ledger'].includes(game.state.locationId))){const r=await invoke('triggerEncounter',{id:targeted.id});if(r.ok){openEncounter(r.encounter);return;}}dialog.open(e.name,'archive',{eyebrow:'LOCAL ARCHIVE'});const lore=LORE.find(l=>l.id===e.data?.loreId);dialog.html(`<p>${esc(e.data?.localLore||e.text||game.currentBody?.lore||'The records of the people who made a life here.')}</p>${lore?`<h3>${esc(lore.title)}</h3><p>${esc(lore.text)}</p>`:''}`);dialog.choices([{label:'Open the collected archive',action:async()=>openJournal('lore')},{label:'Step away from the terminal',action:async()=>dialog.close()}]);processEvents();saveNow();}
function openEncounter(encounter){if(!encounter)return;dialog.open(encounter.title,'encounter',{eyebrow:(encounter.tag??'ENCOUNTER')+' / '+(game.state.mode==='ship'?'INCOMING TRANSMISSION':'A STORY IN PROGRESS')});dialog.html(`<p>${esc(encounter.text)}</p>`);dialog.choices(encounter.choices.map((c,i)=>({label:c.label,detail:c.text,disabled:!game.choiceAvailable(encounter.id,i),action:async()=>{const r=await invoke('applyChoice',{encounterId:encounter.id,choice:i});if(!result(r))return;dialog.open(encounter.title,'result',{eyebrow:'A CHOICE REMEMBERED'});dialog.html(`<p>${esc(r.text)}</p><div class="result-note">${effectSummary(c.effects)||'Your decision has been recorded in your captain’s log.'}</div>`);dialog.choices([{label:game.hasFlag('earth_decision')?'Keep exploring':'Continue your voyage',action:async()=>dialog.close()}]);audio.play('quest');saveNow();}})));}
function effectSummary(fx={}){const parts=[];if(fx.credits)parts.push(`${fx.credits>0?'+':''}${fx.credits} credits`);if(fx.ore)parts.push(`${fx.ore>0?'+':''}${fx.ore} ore`);if(fx.fuel)parts.push(`${fx.fuel>0?'+':''}${fx.fuel} fuel`);for(const[id,n]of Object.entries(fx.rep??{}))parts.push(`${esc(FACTIONS.find(f=>f.id===id)?.name??id)} ${n>0?'+':''}${n}`);return parts.join(' · ');}
function openJobs(){if(game.state.mode!=='person'){openJournal('missions');return;}dialog.open('The contract exchange','jobs',{eyebrow:(game.currentBody?.name??surface?.name??'PORT')+' / '+fmt(game.state.credits)+' CR'});dialog.html('<p class="section-note">Keep a small ship working. Take a contract, do the work in the world, then return to its destination to collect payment.</p>');const active=game.state.missions.filter(m=>m.status!=='completed');if(active.length){const h=document.createElement('h3');h.textContent='Your active contracts';dialog.body.append(h);for(const job of active)jobCard(job,true);}const h=document.createElement('h3');h.textContent='Work available here';dialog.body.append(h);const jobs=game.availableJobs().filter(j=>j.status==='available');if(!jobs.length){const p=document.createElement('p');p.textContent='You have taken the current offers. Other ports have their own exchange.';dialog.body.append(p);}for(const job of jobs)jobCard(job,false);const note=document.createElement('p');note.className='mini muted';note.textContent='Freight crates and survey samples also pay small local stipends. Keep some ore for upgrades before selling the rest.';dialog.body.append(note);}
function jobCard(job,active){const card=document.createElement('div');card.className='entry-card';const target=game.galaxy.find(s=>s.id===job.targetSystem)?.bodies.find(b=>b.id===job.targetBody);card.innerHTML=`<div class="entry-top"><span class="entry-title">${esc(job.title)}</span><span class="entry-meta">${fmt(job.reward)} CR</span></div><p>${esc(job.description)}</p><div class="entry-foot"><span class="mini muted">${esc(target?.name??job.targetBody)}${active?` · ${job.progress} / ${job.goal}`:''}</span><div class="job-actions"></div></div>`;const actions=card.querySelector('.job-actions');if(active){const ready=job.status==='ready'&&game.state.locationId===job.targetBody&&game.state.systemId===job.targetSystem;if(ready){const b=document.createElement('button');b.textContent='Collect payment';b.onclick=async()=>{if(result(await invoke('turnInJob',{id:job.id}))){audio.play('quest');openJobs();}};actions.append(b);}else{const b=document.createElement('button');b.textContent=job.status==='ready'?'Track destination':'Track work';b.onclick=async()=>{dialog.close();trackJob(job);};actions.append(b);}}else{const b=document.createElement('button');b.textContent='Take contract';b.onclick=async()=>{if(result(await invoke('acceptJob',{id:job.id}))){trackJob(job);dialog.close();toast(job.type==='work'?'Find the three amber relays. Calibrate each one, then return to the contract exchange.':job.description,'good',6500);}};actions.append(b);}dialog.body.append(card);}
function trackJob(job){if(game.state.systemId!==job.targetSystem){openMap(job.targetSystem);return;}if(job.type==='work'&&surface&&job.targetBody===game.state.locationId){const next=surface.entities.find(e=>e.type==='work'&&!game.state.activityTokens.some(t=>t.endsWith(':work:'+e.id+':'+job.id)));surfaceTarget=next?.id??surface.entities.find(e=>e.type==='jobboard')?.id;toast(next?'Maintenance relay marked on your local map.':'Return to the contract exchange.');}else if(job.type==='delivery'||job.type==='work'||job.status==='ready'){tracked=job.targetBody;if(game.state.mode==='person'&&job.targetBody!==game.state.locationId)toast('Return to Cinder and fly to the marked destination.');}else if(job.type==='mining'){const a=game.system.asteroids.find(a=>a.hp>0);tracked=a?.id;toast('Mining belt tracked. Launch, move near a rock, then hold MINE.');}else if(job.type==='survey'){tracked=game.system.signals.find(s=>!s.resolved)?.id;toast('A signal is tracked. Approach it and use SCAN.');}else if(job.type==='bounty'){tracked=game.system.enemies[0]?.id;toast('Hostile contact tracked. Use your shield, keep moving, and watch the reactor.');}}
function shipPreview(c,classId,size=108){c.width=128;c.height=128;const g=c.getContext('2d');g.imageSmoothingEnabled=false;g.fillStyle='#091423';g.fillRect(0,0,128,128);g.strokeStyle='#203a4e';for(let n=0;n<128;n+=16){g.beginPath();g.moveTo(n,0);g.lineTo(n,128);g.moveTo(0,n);g.lineTo(128,n);g.stroke();}drawShip(g,64,64,-.4,'#c3d0c7',1,false,0,false,{classId,size});}

function openOutfitter(e=null,tab='equipment'){if(testSession){openTestControls();return;}
 dialog.open(game.state.locationId==='kettle'?'Iona’s shipyard':'Local shipyard','outfitter',{eyebrow:`${game.currentBody?.name??'PORT'} / ${fmt(game.state.credits)} CR · ${game.state.cargo.ore} ORE`});
 const tabs=document.createElement('div');tabs.className='panel-tabs';for(const[key,label]of [['equipment','Equipment'],['ships','New hulls'],['service','Repairs & trade']]){const b=document.createElement('button');b.className=tab===key?'active':'';b.textContent=label;b.onclick=()=>openOutfitter(null,key);tabs.append(b);}dialog.body.append(tabs);
 if(e)dialogueHeader(e,e.text||DIALOGUE.mechanic.greeting);
 if(tab==='service'){dialog.html('<p>Keep enough ore for your next upgrade. The port’s prices reflect your standing with its faction.</p>');dialog.choices([{label:'Open cargo & services',action:openMarket},{label:'Back to equipment',action:()=>openOutfitter()}]);return;}
 if(tab==='ships'){dialog.body.insertAdjacentHTML('beforeend','<p class="section-note">Start with a working cutter. Earn larger vessels through credits, ore, fold upgrades, and your place in the Earth story. Larger hulls bring larger decks and slower handling.</p>');for(const c of SHIP_CLASSES){const info=game.classInfo(c.id),card=document.createElement('article');card.className='entry-card'+(info.active?' done':'');card.innerHTML=`<div class="ship-profile"><canvas aria-label="${esc(c.name)} silhouette"></canvas><div><span class="eyebrow">${esc(c.subtitle)}</span><h3>${esc(c.name)}</h3><p>${c.berths} berths · ${c.stats.cargoCap} cargo<br>${c.stats.maxHull} hull · ${c.stats.mass}× mass</p></div></div><p>${esc(c.description)}</p><div class="entry-foot"><span class="cost">${info.owned?'OWNED':`${fmt(c.cost)} cr · ${c.ore} ore`}</span><button ${!info.ok?'disabled':''}>${info.active?'Current vessel':info.owned?'Activate this hull':'Commission vessel'}</button></div>${!info.ok&&!info.active?`<p class="mini muted" style="margin-bottom:0">${esc(info.reason)}</p>`:''}`;shipPreview(card.querySelector('canvas'),c.id);card.querySelector('button').onclick=async()=>{if(result(await invoke(info.owned?'selectShip':'buyShip',{id:c.id}))){surfaceKey='';audio.play('quest');openOutfitter(null,'ships');}};dialog.body.append(card);}return;}
 dialog.body.insertAdjacentHTML('beforeend',`<p class="section-note">${esc(getShipClass(game.state.ship.classId).name)} · Fit vector thrusters and an echo scanner before the first fold drive. Installed equipment travels with you when you commission a new hull.</p>`);
 for(const u of UPGRADES){const info=game.upgradeInfo(u.id),owned=!!game.state.upgrades[u.id],card=document.createElement('div');card.className='entry-card'+(owned?' done':'');card.innerHTML=`<div class="entry-top"><span class="entry-title">${esc(u.name)}</span><span class="pill">${esc(u.slot)}</span></div><p>${esc(u.description)}</p><div class="entry-foot"><span class="cost">${u.cost} cr · ${u.ore??0} ore</span><button ${!info.ok?'disabled':''}>${owned?'Installed':info.code==='prerequisite'?'Parts required':'Install upgrade'}</button></div>${!owned&&!info.ok?`<p class="mini muted" style="margin-bottom:0">${esc(info.reason)}</p>`:''}`;card.querySelector('button').onclick=async()=>{if(result(await invoke('buyUpgrade',{id:u.id}))){audio.play('quest');openOutfitter();}};dialog.body.append(card);}
}
function openMarket(){dialog.open('Cargo & port services','market',{eyebrow:(game.currentBody?.name??'PORT')+' / '+fmt(game.state.credits)+' CREDITS'});dialog.html(`<div class="stat-grid"><div class="stat-cell"><small>ORE</small><strong>${game.state.cargo.ore}</strong></div><div class="stat-cell"><small>CRYSTAL</small><strong>${game.state.cargo.crystal}</strong></div><div class="stat-cell"><small>HOLD USED</small><strong>${game.cargoUsed}/${game.state.ship.cargoCap}</strong></div></div><p>Ore is also used for ship upgrades and mining contracts. Local prices reflect your reputation with the port’s faction.</p>`);const items=[];for(const key of ['sellOre','sellCrystal','refuel','repair','emergency']){const q=game.serviceQuote(key);items.push({label:key==='sellOre'?`Sell all ore · ${q.value} cr`:key==='sellCrystal'?`Sell all crystal · ${q.value} cr`:q.label+(q.cost?` · ${q.cost} cr`:''),detail:key==='emergency'?'If you cannot afford to leave, ask the port for enough fuel. You will owe Freewake a favor.':key.startsWith('sell')?'This sells the selected resource from your entire hold.':undefined,disabled:key.startsWith('sell')?!q.value:key==='emergency'?game.state.credits>=24||game.state.ship.fuel>=10:!q.cost||q.cost>game.state.credits,action:async()=>{if(result(await invoke('service',{action:key})))openMarket();}});}items.push({label:'Back to the outfitter',action:async()=>openOutfitter()});dialog.choices(items);}
