 for(const person of snap?.presence??[]){const row=document.createElement('div');row.className='crew-row';const sys=game.galaxy.find(s=>s.id===person.systemId);row.innerHTML=`<div><strong>${esc(person.name)}${person.captainId===mp.captainId?' · YOU':''}</strong><small>${esc(sys?.name??person.systemId)} · ${esc(person.crewRole??'captain')}</small></div><span class="presence ${person.online?'':'away'}">${person.online?'ONLINE':'AWAY'}</span>`;$('captainsList').append(row);}
 const choices=[{label:'Home berth & recovery',detail:'Rent a room, establish an outpost, or register a ship bunk.',action:openHome},{label:'Captain passport',detail:'Back up your captain for another device.',action:()=>openPassport()}];
 if(vessel){choices.push({label:'Shared ship & stations',detail:`${vessel.occupants??1} aboard · ${getShipClass(vessel.classId).name} · ${vessel.berths} berths`,action:openSharedShip});}
