async function disconnectGalaxy(){network?.setInput({});network?.disconnect();network=null;onlineSnapshot=null;worldPresentation.reset();personPredictedAt=null;personVisualAt=null;personVisualOffset={x:0,y:0};playing=false;surface=null;surfaceKey='';connectionState='offline';dialog.close();$('welcome').hidden=false;$('resumeGalaxy').hidden=!readPassport();document.body.classList.add('welcome-active');updateConnectionHUD();}
